use vstd::prelude::*;

verus! {

fn reverse(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> result@[i] == a@[a@.len() - 1 - i],
{
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            n == a.len(),
            i <= n,
            result@.len() == i as int,
            forall|j: int|
                0 <= j < i as int ==> result@[j] == a@[n as int - 1 - j],
        decreases n - i,
    {
        // Push the next element from the back of `a`.
        // Index used: n - 1 - i, which is valid because i < n.
        let idx: usize = n - 1 - i;
        result.push(a[idx]);

        i = i + 1;
    }

    result
}

} // verus!

